Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"
$env:GIT_PAGER = "cat"
$env:NPM_CONFIG_LOGLEVEL = "error"

$Root = (Get-Location).Path
$HomePath = Join-Path $Root "app\page.tsx"
$ComponentPath = Join-Path $Root "components\home\HomeAiChat.tsx"
$RoutePath = Join-Path $Root "app\api\public\home-chat\route.ts"
$BackupRoot = Join-Path $Root ".orcaly-backups\home-ai-chat-$(Get-Date -Format 'yyyyMMdd-HHmmss')"

$ComponentBase64 = @'

'@

$RouteWithRateLimitBase64 = @'

'@

$RouteStandaloneBase64 = @'

'@

function Write-Section([string]$Text) {
    Write-Host ""
    Write-Host ("=" * 68) -ForegroundColor DarkCyan
    Write-Host $Text -ForegroundColor Cyan
    Write-Host ("=" * 68) -ForegroundColor DarkCyan
}

function Get-RelativePathCompat(
    [string]$BasePath,
    [string]$TargetPath
) {
    $Separator = [System.IO.Path]::DirectorySeparatorChar
    $AltSeparator = [System.IO.Path]::AltDirectorySeparatorChar

    $BaseFull = [System.IO.Path]::GetFullPath($BasePath)
    $BaseFull = $BaseFull.TrimEnd(
        [char[]]@($Separator, $AltSeparator)
    )
    $BaseFull = $BaseFull + $Separator

    $TargetFull = [System.IO.Path]::GetFullPath($TargetPath)

    $BaseUri = New-Object System.Uri($BaseFull)
    $TargetUri = New-Object System.Uri($TargetFull)

    $RelativeUri = $BaseUri.MakeRelativeUri($TargetUri)
    $RelativePath = [System.Uri]::UnescapeDataString(
        $RelativeUri.ToString()
    )

    return $RelativePath.Replace(
        "/",
        [string]$Separator
    )
}

function Write-Utf8File(
    [string]$Path,
    [string]$Base64
) {
    $Parent = Split-Path -Parent $Path

    if ($Parent) {
        New-Item -ItemType Directory -Path $Parent -Force | Out-Null
    }

    $Bytes = [Convert]::FromBase64String(
        ($Base64 -replace "\s", "")
    )

    [System.IO.File]::WriteAllBytes($Path, $Bytes)
}

function Backup-File([string]$Path) {
    if (-not (Test-Path -LiteralPath $Path)) {
        return
    }

    $Relative = Get-RelativePathCompat -BasePath $Root -TargetPath $Path
    $Destination = Join-Path $BackupRoot $Relative
    $Parent = Split-Path -Parent $Destination

    New-Item -ItemType Directory -Path $Parent -Force | Out-Null
    Copy-Item -LiteralPath $Path -Destination $Destination -Force
}

function Restore-Files {
    Write-Host "[AVISO] Restaurando arquivos anteriores..." -ForegroundColor Yellow

    foreach ($Path in @($HomePath, $ComponentPath, $RoutePath)) {
        $Relative = Get-RelativePathCompat -BasePath $Root -TargetPath $Path
        $Backup = Join-Path $BackupRoot $Relative

        if (Test-Path -LiteralPath $Backup) {
            New-Item `
                -ItemType Directory `
                -Path (Split-Path -Parent $Path) `
                -Force | Out-Null

            Copy-Item -LiteralPath $Backup -Destination $Path -Force
        }
        elseif (Test-Path -LiteralPath $Path) {
            Remove-Item -LiteralPath $Path -Force
        }
    }
}

Write-Section "ORCALY - CHAT COM IA NA HOME V4"

if (-not (Test-Path -LiteralPath (Join-Path $Root "package.json"))) {
    throw "Execute este script na raiz do projeto Orçaly."
}

if (-not (Test-Path -LiteralPath $HomePath)) {
    throw "Arquivo app/page.tsx não encontrado."
}

New-Item -ItemType Directory -Path $BackupRoot -Force | Out-Null

Backup-File $HomePath
Backup-File $ComponentPath
Backup-File $RoutePath

try {
    Write-Section "CRIANDO O WIDGET E A API"

    Write-Utf8File $ComponentPath $ComponentBase64

    if (Test-Path -LiteralPath (Join-Path $Root "lib\security\rate-limit.ts")) {
        Write-Utf8File $RoutePath $RouteWithRateLimitBase64
        Write-Host "[OK] API criada com rate limit persistente." -ForegroundColor Green
    }
    else {
        Write-Utf8File $RoutePath $RouteStandaloneBase64
        Write-Host "[AVISO] lib/security/rate-limit.ts não existe. API criada sem o rate limit persistente." -ForegroundColor Yellow
    }

    $HomeContent = [System.IO.File]::ReadAllText(
        $HomePath,
        [System.Text.Encoding]::UTF8
    )

    if (-not $HomeContent.Contains("HomeAiChat")) {
        $Import = "import HomeAiChat from '@/components/home/HomeAiChat'"

        $LastImportIndex = $HomeContent.LastIndexOf("import ")

        if ($LastImportIndex -lt 0) {
            throw "Não foi possível localizar os imports da Home."
        }

        $ImportLineEnd = $HomeContent.IndexOf(
            [Environment]::NewLine,
            $LastImportIndex
        )

        if ($ImportLineEnd -lt 0) {
            $ImportLineEnd = $HomeContent.IndexOf(
                "`n",
                $LastImportIndex
            )
        }

        if ($ImportLineEnd -lt 0) {
            throw "Não foi possível inserir o import do chat."
        }

        $HomeContent = $HomeContent.Insert(
            $ImportLineEnd + 1,
            "$Import`r`n"
        )
    }

    if (-not $HomeContent.Contains("<HomeAiChat />")) {
        $MainClose = $HomeContent.LastIndexOf("</main>")

        if ($MainClose -lt 0) {
            throw "Não foi possível localizar o fechamento principal da Home."
        }

        $HomeContent = $HomeContent.Insert(
            $MainClose,
            "      <HomeAiChat />`r`n"
        )
    }

    [System.IO.File]::WriteAllText(
        $HomePath,
        $HomeContent,
        [System.Text.UTF8Encoding]::new($false)
    )

    Write-Host "[OK] components/home/HomeAiChat.tsx" -ForegroundColor Green
    Write-Host "[OK] app/api/public/home-chat/route.ts" -ForegroundColor Green
    Write-Host "[OK] app/page.tsx integrado" -ForegroundColor Green

    Write-Section "VALIDANDO CONTEÚDO"

    $Checks = @{
        $HomePath = @(
            "HomeAiChat",
            "<HomeAiChat />"
        )
        $ComponentPath = @(
            "ORCALY_HOME_AI_CHAT_V1",
            "💭",
            "Assistente Orçaly",
            "quickQuestions",
            "/api/public/home-chat",
            "orcalybr@gmail.com"
        )
        $RoutePath = @(
            "ORCALY_HOME_AI_CHAT_API_V1",
            "AI_GATEWAY_API_KEY",
            "openai/gpt-5.4-mini",
            "R$ 49,90",
            "R$ 99,90",
            "R$ 149,90",
            "guidedAnswer"
        )
    }

    foreach ($Entry in $Checks.GetEnumerator()) {
        $Content = [System.IO.File]::ReadAllText(
            $Entry.Key,
            [System.Text.Encoding]::UTF8
        )

        foreach ($Text in $Entry.Value) {
            if (-not $Content.Contains($Text)) {
                throw "Validação falhou em $($Entry.Key): $Text"
            }

            Write-Host "[OK] $Text" -ForegroundColor Green
        }
    }

    git --no-pager diff --check -- `
        "app/page.tsx" `
        "components/home/HomeAiChat.tsx" `
        "app/api/public/home-chat/route.ts"

    if ($LASTEXITCODE -ne 0) {
        throw "git diff --check encontrou problemas."
    }

    $Package = Get-Content `
        -LiteralPath (Join-Path $Root "package.json") `
        -Raw |
        ConvertFrom-Json

    if ($Package.scripts.PSObject.Properties.Name -contains "security:check") {
        Write-Section "VALIDANDO SEGURANÇA"

        npm run security:check

        if ($LASTEXITCODE -ne 0) {
            throw "security:check falhou."
        }

        Write-Host "[OK] SECURITY_CHECK_EXIT_CODE=0" -ForegroundColor Green
    }

    Remove-Item `
        -LiteralPath (Join-Path $Root ".next") `
        -Recurse `
        -Force `
        -ErrorAction SilentlyContinue

    Write-Section "EXECUTANDO BUILD COMPLETO"

    npm run build
    $BuildExitCode = $LASTEXITCODE

    Write-Host ""
    Write-Host "BUILD_EXIT_CODE=$BuildExitCode" -ForegroundColor Yellow

    if ($BuildExitCode -ne 0) {
        throw "O build falhou."
    }

    Write-Section "CHAT DA HOME APLICADO"

    Write-Host "Widget: components/home/HomeAiChat.tsx"
    Write-Host "API: app/api/public/home-chat/route.ts"
    Write-Host "Integração: app/page.tsx"
    Write-Host "Backup: $BackupRoot"
    Write-Host "Build: aprovado"
    Write-Host "Commit: não realizado"
    Write-Host "Deploy: não realizado"
    Write-Host ""
    Write-Host "Modo guiado: ativo mesmo sem chave externa"
    Write-Host "IA generativa: ativada quando AI_GATEWAY_API_KEY existir na Vercel"
    Write-Host "Modelo padrão: openai/gpt-5.4-mini"
}
catch {
    Restore-Files
    throw
}
